INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000660', 'Viskositas fluida adalah ukuran...', 'Fluid viscosity is a measure of...', 'option', 'PFC000000003', 'Inisialisasi', 'a:4:{i:0;s:54:"Kemampuan fluida mengalir (resistensi terhadap aliran)";i:1;s:26:"Kandungan gas dalam minyak";i:2;s:18:"Berat jenis fluida";i:3;s:27:"Tekanan fluida di reservoir";}', 'a:4:{i:0;s:51:"The ability of a fluid to flow (resistance to flow)";i:1;s:22:"The gas content in oil";i:2;s:33:"The specific gravity of the fluid";i:3;s:35:"The fluid pressure in the reservoir";}', '', 'Kemampuan fluida mengalir (resistensi terhadap aliran)', 'The ability of a fluid to flow (resistance to flow)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000661', 'Faktor volume formasi minyak (Bo) menyatakan...', 'The oil formation volume factor (Bo) expresses...', 'option', 'PFC000000003', 'Inisialisasi', 'a:4:{i:0;s:30:"Berat minyak per satuan volume";i:1;s:39:"Perbandingan volume gas terhadap minyak";i:2;s:22:"Kadar air dalam minyak";i:3;s:68:"Perbandingan volume minyak di reservoir terhadap volume di permukaan";}', 'a:4:{i:0;s:33:"The weight of oil per unit volume";i:1;s:37:"The ratio of gas volume to oil volume";i:2;s:28:"The water content in the oil";i:3;s:69:"The ratio of oil volume in the reservoir to its volume at the surface";}', '', 'Perbandingan volume minyak di reservoir terhadap volume di permukaan', 'The ratio of oil volume in the reservoir to its volume at the surface', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000662', 'Kelarutan gas dalam minyak biasanya dinyatakan dengan simbol...', 'Gas solubility in oil is usually denoted by the symbol...', 'option', 'PFC000000003', 'Inisialisasi', 'a:4:{i:0;s:2:"Rs";i:1;s:2:"Bo";i:2;s:2:"Bw";i:3;s:1:"Z";}', 'a:4:{i:0;s:2:"Rs";i:1;s:2:"Bo";i:2;s:2:"Bw";i:3;s:1:"Z";}', '', 'Rs', 'Rs', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000663', 'Bubble point pressure adalah tekanan ketika...', 'Bubble point pressure is the pressure at which...', 'option', 'PFC000000003', 'Inisialisasi', 'a:4:{i:0;s:14:"Minyak membeku";i:1;s:43:"Gas pertama kali keluar dari larutan minyak";i:2;s:24:"Porositas batuan berubah";i:3;s:17:"Air mulai menguap";}', 'a:4:{i:0;s:11:"Oil freezes";i:1;s:39:"Gas first comes out of the oil solution";i:2;s:21:"Rock porosity changes";i:3;s:25:"Water starts to evaporate";}', '', 'Gas pertama kali keluar dari larutan minyak', 'Gas first comes out of the oil solution', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000664', 'Dew point pressure pada reservoir gas adalah tekanan ketika...', 'Dew point pressure in a gas reservoir is the pressure at which...', 'option', 'PFC000000003', 'Inisialisasi', 'a:4:{i:0;s:34:"Gas mulai mengembun menjadi cairan";i:1;s:21:"Air mulai terproduksi";i:2;s:21:"Gas berhenti mengalir";i:3;s:20:"Minyak mulai menguap";}', 'a:4:{i:0;s:34:"Gas begins to condense into liquid";i:1;s:27:"Water begins to be produced";i:2;s:17:"Gas stops flowing";i:3;s:22:"Oil begins to vaporize";}', '', 'Gas mulai mengembun menjadi cairan', 'Gas begins to condense into liquid', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000665', 'Minyak dengan nilai API gravity tinggi umumnya bersifat...', 'Oil with a high API gravity value is generally...', 'option', 'PFC000000003', 'Inisialisasi', 'a:4:{i:0;s:24:"Ringan dan kurang kental";i:1;s:20:"Tidak dapat mengalir";i:2;s:31:"Selalu mengandung banyak sulfur";i:3;s:23:"Berat dan sangat kental";}', 'a:4:{i:0;s:22:"Light and less viscous";i:1;s:14:"Unable to flow";i:2;s:21:"Always high in sulfur";i:3;s:22:"Heavy and very viscous";}', '', 'Ringan dan kurang kental', 'Light and less viscous', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000666', 'Kompresibilitas fluida menggambarkan...', 'Fluid compressibility describes...', 'option', 'PFC000000003', 'Inisialisasi', 'a:4:{i:0;s:34:"Kemampuan fluida melarutkan batuan";i:1;s:48:"Perubahan volume fluida akibat perubahan tekanan";i:2;s:22:"Perubahan warna fluida";i:3;s:23:"Kecepatan aliran fluida";}', 'a:4:{i:0;s:41:"The ability of the fluid to dissolve rock";i:1;s:51:"The change in fluid volume due to a pressure change";i:2;s:25:"The change in fluid color";i:3;s:23:"The fluid flow velocity";}', '', 'Perubahan volume fluida akibat perubahan tekanan', 'The change in fluid volume due to a pressure change', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000667', 'Manakah yang termasuk sifat fisik fluida reservoir?', 'Which of the following are physical properties of reservoir fluids?', 'multi', 'PFC000000003', 'Inisialisasi', 'a:4:{i:0;s:21:"Faktor volume formasi";i:1;s:10:"Viskositas";i:2;s:16:"Porositas batuan";i:3;s:13:"Kelarutan gas";}', 'a:4:{i:0;s:23:"Formation volume factor";i:1;s:9:"Viscosity";i:2;s:13:"Rock porosity";i:3;s:14:"Gas solubility";}', '', 'a:3:{i:0;s:10:"Viskositas";i:1;s:21:"Faktor volume formasi";i:2;s:13:"Kelarutan gas";}', 'a:3:{i:0;s:9:"Viscosity";i:1;s:23:"Formation volume factor";i:2;s:14:"Gas solubility";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000668', 'Urutkan jenis minyak dari yang paling ringan ke paling berat berdasarkan API gravity.', 'Arrange oil types from lightest to heaviest based on API gravity.', 'drag', 'PFC000000003', 'Inisialisasi', 'a:5:{i:0;s:22:"Light oil (API > 31,1)";i:1;s:28:"Medium oil (API 22,3 - 31,1)";i:2;s:20:"Kondensat (API > 45)";i:3;s:25:"Heavy oil (API 10 - 22,3)";i:4;s:26:"Extra heavy oil (API < 10)";}', 'a:5:{i:0;s:22:"Light oil (API > 31.1)";i:1;s:28:"Medium oil (API 22.3 - 31.1)";i:2;s:21:"Condensate (API > 45)";i:3;s:25:"Heavy oil (API 10 - 22.3)";i:4;s:26:"Extra heavy oil (API < 10)";}', '', 'a:4:{i:0;s:22:"Light oil (API > 31,1)";i:1;s:28:"Medium oil (API 22,3 - 31,1)";i:2;s:25:"Heavy oil (API 10 - 22,3)";i:3;s:26:"Extra heavy oil (API < 10)";}', 'a:4:{i:0;s:22:"Light oil (API > 31.1)";i:1;s:28:"Medium oil (API 22.3 - 31.1)";i:2;s:25:"Heavy oil (API 10 - 22.3)";i:3;s:26:"Extra heavy oil (API < 10)";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000669', 'Benarkah viskositas minyak umumnya menurun ketika suhu meningkat?', 'Is it true that oil viscosity generally decreases as temperature increases?', 'yesorno', 'PFC000000003', 'Inisialisasi', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000670', 'Minyak memiliki specific gravity 0,85. Berapa API gravity-nya?', 'An oil has a specific gravity of 0.85. What is its API gravity?', 'option', 'PFC000000003', 'Final Advanced', 'a:4:{i:0;s:8:"34,9 API";i:1;s:8:"15,0 API";i:2;s:8:"45,1 API";i:3;s:8:"85,0 API";}', 'a:4:{i:0;s:8:"34.9 API";i:1;s:8:"15.0 API";i:2;s:8:"45.1 API";i:3;s:8:"85.0 API";}', '', '34,9 API', '34.9 API', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000671', 'Jika Bo = 1,3 RB/STB, maka 1000 STB minyak di permukaan setara dengan... di reservoir.', 'If Bo = 1.3 RB/STB, then 1000 STB of oil at the surface corresponds to... in the reservoir.', 'option', 'PFC000000003', 'Final Advanced', 'a:4:{i:0;s:7:"1300 RB";i:1;s:6:"770 RB";i:2;s:7:"1000 RB";i:3;s:8:"13000 RB";}', 'a:4:{i:0;s:7:"1300 RB";i:1;s:6:"770 RB";i:2;s:7:"1000 RB";i:3;s:8:"13000 RB";}', '', '1300 RB', '1300 RB', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000672', 'Ketika tekanan reservoir turun di bawah bubble point, gas yang keluar dari larutan menyebabkan...', 'When reservoir pressure drops below the bubble point, gas coming out of solution causes...', 'option', 'PFC000000003', 'Final Advanced', 'a:4:{i:0;s:42:"Bo menurun dan viskositas minyak meningkat";i:1;s:27:"Minyak menjadi lebih ringan";i:2;s:35:"Bo meningkat dan viskositas menurun";i:3;s:32:"Tidak ada perubahan sifat fluida";}', 'a:4:{i:0;s:44:"Bo to decrease and oil viscosity to increase";i:1;s:25:"The oil to become lighter";i:2;s:40:"Bo to increase and viscosity to decrease";i:3;s:29:"No change in fluid properties";}', '', 'Bo menurun dan viskositas minyak meningkat', 'Bo to decrease and oil viscosity to increase', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000673', 'Faktor kompresibilitas gas (Z) digunakan untuk...', 'The gas compressibility factor (Z) is used to...', 'option', 'PFC000000003', 'Final Advanced', 'a:4:{i:0;s:22:"Menentukan wettability";i:1;s:27:"Menghitung porositas batuan";i:2;s:48:"Mengoreksi perilaku gas nyata terhadap gas ideal";i:3;s:30:"Mengukur permeabilitas relatif";}', 'a:4:{i:0;s:21:"Determine wettability";i:1;s:23:"Calculate rock porosity";i:2;s:47:"Correct real gas behavior relative to ideal gas";i:3;s:29:"Measure relative permeability";}', '', 'Mengoreksi perilaku gas nyata terhadap gas ideal', 'Correct real gas behavior relative to ideal gas', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000674', 'Reservoir dikategorikan undersaturated apabila tekanan reservoir...', 'A reservoir is classified as undersaturated when the reservoir pressure is...', 'option', 'PFC000000003', 'Final Advanced', 'a:4:{i:0;s:30:"Lebih tinggi dari bubble point";i:1;s:24:"Sama dengan bubble point";i:2;s:30:"Lebih rendah dari bubble point";i:3;s:28:"Sama dengan tekanan atmosfer";}', 'a:4:{i:0;s:28:"Higher than the bubble point";i:1;s:25:"Equal to the bubble point";i:2;s:27:"Lower than the bubble point";i:3;s:29:"Equal to atmospheric pressure";}', '', 'Lebih tinggi dari bubble point', 'Higher than the bubble point', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000675', 'Retrograde condensation terjadi pada reservoir gas-kondensat ketika tekanan...', 'Retrograde condensation occurs in a gas-condensate reservoir when the pressure...', 'option', 'PFC000000003', 'Final Advanced', 'a:4:{i:0;s:46:"Naik di atas dew point sehingga cairan menguap";i:1;s:30:"Sama dengan tekanan kritis air";i:2;s:50:"Turun di bawah dew point sehingga cairan mengembun";i:3;s:32:"Tetap konstan sepanjang produksi";}', 'a:4:{i:0;s:45:"Rises above the dew point so liquid vaporizes";i:1;s:37:"Equals the critical pressure of water";i:2;s:45:"Falls below the dew point so liquid condenses";i:3;s:38:"Remains constant throughout production";}', '', 'Turun di bawah dew point sehingga cairan mengembun', 'Falls below the dew point so liquid condenses', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000676', 'Gradien tekanan fluida di reservoir digunakan untuk menentukan...', 'Fluid pressure gradients in a reservoir are used to determine...', 'option', 'PFC000000003', 'Final Advanced', 'a:4:{i:0;s:43:"Kontak fluida (GOC/WOC) dan densitas fluida";i:1;s:13:"Kadar lempung";i:2;s:20:"Kekuatan semen sumur";i:3;s:16:"Porositas batuan";}', 'a:4:{i:0;s:44:"Fluid contacts (GOC/WOC) and fluid densities";i:1;s:12:"Clay content";i:2;s:20:"Well cement strength";i:3;s:13:"Rock porosity";}', '', 'Kontak fluida (GOC/WOC) dan densitas fluida', 'Fluid contacts (GOC/WOC) and fluid densities', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000677', 'Minyak berat (heavy oil) umumnya memiliki...', 'Heavy oil generally has...', 'option', 'PFC000000003', 'Final Advanced', 'a:4:{i:0;s:32:"API tinggi dan viskositas rendah";i:1;s:32:"API rendah dan viskositas rendah";i:2;s:32:"API tinggi dan viskositas tinggi";i:3;s:32:"API rendah dan viskositas tinggi";}', 'a:4:{i:0;s:26:"High API and low viscosity";i:1;s:25:"Low API and low viscosity";i:2;s:27:"High API and high viscosity";i:3;s:26:"Low API and high viscosity";}', '', 'API rendah dan viskositas tinggi', 'Low API and high viscosity', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000678', 'Kelarutan gas (Rs) yang tinggi pada minyak umumnya menyebabkan...', 'High gas solubility (Rs) in oil generally causes...', 'option', 'PFC000000003', 'Final Advanced', 'a:4:{i:0;s:35:"Bo menurun dan viskositas meningkat";i:1;s:25:"Tidak berpengaruh pada Bo";i:2;s:26:"Minyak menjadi lebih berat";i:3;s:35:"Bo meningkat dan viskositas menurun";}', 'a:4:{i:0;s:40:"Bo to decrease and viscosity to increase";i:1;s:15:"No effect on Bo";i:2;s:25:"The oil to become heavier";i:3;s:40:"Bo to increase and viscosity to decrease";}', '', 'Bo meningkat dan viskositas menurun', 'Bo to increase and viscosity to decrease', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000679', 'Salinitas air formasi penting diketahui karena memengaruhi...', 'Formation water salinity is important because it affects...', 'option', 'PFC000000003', 'Final Advanced', 'a:4:{i:0;s:22:"Porositas total batuan";i:1;s:15:"Kedalaman sumur";i:2;s:12:"Warna minyak";i:3;s:55:"Pembacaan log resistivitas dan perhitungan saturasi air";}', 'a:4:{i:0;s:19:"Total rock porosity";i:1;s:10:"Well depth";i:2;s:9:"Oil color";i:3;s:58:"Resistivity log readings and water saturation calculations";}', '', 'Pembacaan log resistivitas dan perhitungan saturasi air', 'Resistivity log readings and water saturation calculations', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000680', 'Tegangan antarmuka (IFT) yang rendah antara minyak dan air berpengaruh terhadap...', 'Low interfacial tension (IFT) between oil and water affects...', 'option', 'PFC000000003', 'Final Advanced', 'a:4:{i:0;s:68:"Meningkatnya bilangan kapiler sehingga mobilisasi minyak lebih mudah";i:1;s:27:"Meningkatnya viskositas air";i:2;s:28:"Meningkatnya densitas batuan";i:3;s:28:"Menurunnya porositas efektif";}', 'a:4:{i:0;s:63:"An increase in capillary number, making oil mobilization easier";i:1;s:30:"An increase in water viscosity";i:2;s:27:"An increase in rock density";i:3;s:32:"A decrease in effective porosity";}', '', 'Meningkatnya bilangan kapiler sehingga mobilisasi minyak lebih mudah', 'An increase in capillary number, making oil mobilization easier', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000681', 'Faktor volume formasi air (Bw) umumnya bernilai...', 'The water formation volume factor (Bw) is generally...', 'option', 'PFC000000003', 'Final Advanced', 'a:4:{i:0;s:17:"Jauh di bawah 0,5";i:1;s:16:"Selalu tepat 2,0";i:2;s:19:"Sedikit di atas 1,0";i:3;s:14:"Sama dengan Bo";}', 'a:4:{i:0;s:13:"Far below 0.5";i:1;s:18:"Always exactly 2.0";i:2;s:18:"Slightly above 1.0";i:3;s:11:"Equal to Bo";}', '', 'Sedikit di atas 1,0', 'Slightly above 1.0', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000682', 'Manakah data fluida yang diperlukan untuk perhitungan material balance reservoir minyak?', 'Which fluid data are required for oil reservoir material balance calculations?', 'multi', 'PFC000000003', 'Final Advanced', 'a:4:{i:0;s:12:"Warna minyak";i:1;s:2:"Rs";i:2;s:2:"Bo";i:3;s:30:"Viskositas dan kompresibilitas";}', 'a:4:{i:0;s:9:"Oil color";i:1;s:2:"Rs";i:2;s:2:"Bo";i:3;s:29:"Viscosity and compressibility";}', '', 'a:3:{i:0;s:2:"Bo";i:1;s:2:"Rs";i:2;s:30:"Viskositas dan kompresibilitas";}', 'a:3:{i:0;s:2:"Bo";i:1;s:2:"Rs";i:2;s:29:"Viscosity and compressibility";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000683', 'Manakah yang memengaruhi viskositas minyak reservoir?', 'Which of the following affect reservoir oil viscosity?', 'multi', 'PFC000000003', 'Final Advanced', 'a:4:{i:0;s:22:"Kandungan gas terlarut";i:1;s:14:"Suhu reservoir";i:2;s:22:"Warna batuan reservoir";i:3;s:34:"Komposisi dan berat molekul minyak";}', 'a:4:{i:0;s:21:"Dissolved gas content";i:1;s:21:"Reservoir temperature";i:2;s:20:"Reservoir rock color";i:3;s:36:"Oil composition and molecular weight";}', '', 'a:3:{i:0;s:14:"Suhu reservoir";i:1;s:22:"Kandungan gas terlarut";i:2;s:34:"Komposisi dan berat molekul minyak";}', 'a:3:{i:0;s:21:"Reservoir temperature";i:1;s:21:"Dissolved gas content";i:2;s:36:"Oil composition and molecular weight";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000684', 'Manakah pernyataan yang benar tentang gas alam?', 'Which statements about natural gas are correct?', 'multi', 'PFC000000003', 'Final Advanced', 'a:4:{i:0;s:45:"Mengikuti persamaan gas nyata dengan faktor Z";i:1;s:31:"Gas tidak dapat larut dalam air";i:2;s:54:"Viskositas gas jauh lebih kecil dari viskositas minyak";i:3;s:43:"Specific gravity gas biasanya kurang dari 1";}', 'a:4:{i:0;s:48:"It follows the real gas equation with a Z factor";i:1;s:28:"Gas cannot dissolve in water";i:2;s:46:"Gas viscosity is much lower than oil viscosity";i:3;s:43:"Gas specific gravity is usually less than 1";}', '', 'a:3:{i:0;s:45:"Mengikuti persamaan gas nyata dengan faktor Z";i:1;s:43:"Specific gravity gas biasanya kurang dari 1";i:2;s:54:"Viskositas gas jauh lebih kecil dari viskositas minyak";}', 'a:3:{i:0;s:48:"It follows the real gas equation with a Z factor";i:1;s:43:"Gas specific gravity is usually less than 1";i:2;s:46:"Gas viscosity is much lower than oil viscosity";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000685', 'Manakah yang perlu diukur dalam analisis PVT laboratorium?', 'Which of the following must be measured in laboratory PVT analysis?', 'multi', 'PFC000000003', 'Final Advanced', 'a:4:{i:0;s:39:"Rs dan viskositas pada berbagai tekanan";i:1;s:14:"Bo, Bg, dan Bw";i:2;s:10:"Warna core";i:3;s:36:"Bubble point atau dew point pressure";}', 'a:4:{i:0;s:37:"Rs and viscosity at various pressures";i:1;s:14:"Bo, Bg, and Bw";i:2;s:10:"Core color";i:3;s:34:"Bubble point or dew point pressure";}', '', 'a:3:{i:0;s:36:"Bubble point atau dew point pressure";i:1;s:14:"Bo, Bg, dan Bw";i:2;s:39:"Rs dan viskositas pada berbagai tekanan";}', 'a:3:{i:0;s:34:"Bubble point or dew point pressure";i:1;s:14:"Bo, Bg, and Bw";i:2;s:37:"Rs and viscosity at various pressures";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000686', 'Urutkan tahapan perubahan kondisi fluida reservoir saat tekanan menurun dari atas bubble point.', 'Arrange the changes in reservoir fluid condition as pressure declines from above the bubble point.', 'drag', 'PFC000000003', 'Final Advanced', 'a:5:{i:0;s:49:"Gas terlarut kembali ke minyak (repressurization)";i:1;s:45:"Undersaturated (tekanan di atas bubble point)";i:2;s:21:"Mencapai bubble point";i:3;s:29:"Gas mulai keluar dari larutan";i:4;s:34:"Produksi dua fase (minyak dan gas)";}', 'a:5:{i:0;s:47:"Dissolved gas returns to oil (repressurization)";i:1;s:44:"Undersaturated (pressure above bubble point)";i:2;s:25:"Reaching the bubble point";i:3;s:34:"Gas begins to come out of solution";i:4;s:34:"Two-phase production (oil and gas)";}', '', 'a:4:{i:0;s:45:"Undersaturated (tekanan di atas bubble point)";i:1;s:21:"Mencapai bubble point";i:2;s:29:"Gas mulai keluar dari larutan";i:3;s:34:"Produksi dua fase (minyak dan gas)";}', 'a:4:{i:0;s:44:"Undersaturated (pressure above bubble point)";i:1;s:25:"Reaching the bubble point";i:2;s:34:"Gas begins to come out of solution";i:3;s:34:"Two-phase production (oil and gas)";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000687', 'Urutkan fluida reservoir dari yang paling atas ke paling bawah berdasarkan densitasnya.', 'Arrange reservoir fluids from top to bottom based on density.', 'drag', 'PFC000000003', 'Final Advanced', 'a:4:{i:0;s:25:"Batuan penutup (cap rock)";i:1;s:3:"Gas";i:2;s:6:"Minyak";i:3;s:11:"Air formasi";}', 'a:4:{i:0;s:8:"Cap rock";i:1;s:3:"Gas";i:2;s:3:"Oil";i:3;s:15:"Formation water";}', '', 'a:3:{i:0;s:3:"Gas";i:1;s:6:"Minyak";i:2;s:11:"Air formasi";}', 'a:3:{i:0;s:3:"Gas";i:1;s:3:"Oil";i:2;s:15:"Formation water";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000688', 'Benarkah viskositas fluida yang tinggi membuat fluida lebih sulit terproduksi?', 'Is it true that high fluid viscosity makes the fluid harder to produce?', 'yesorno', 'PFC000000003', 'Final Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000689', 'Benarkah nilai Bo selalu lebih kecil dari 1?', 'Is it true that Bo is always less than 1?', 'yesorno', 'PFC000000003', 'Final Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
